    string full = Path.GetFullPath(path), directory = Path.GetDirectoryName(full)!;
    var prepared=PrepareSave?.Invoke(Copy(document),BaseDirectory)??document;
    var rebased = Rebase(prepared, BaseDirectory, directory);
    SolutionStore.Save(full, rebased); // Commit editor state only after an atomic successful write.
    document = rebased; BaseDirectory = directory; FilePath = full; IsDirty = false; Revision++; Changed?.Invoke();
}
public void SelectProcedure(string id) { if (!document.Procedures.Any(p => p.Id == id)) throw new KeyNotFoundException(id); if(CurrentProcedureId == id)return; CurrentProcedureId = id; Changed?.Invoke(); }

    void OpenSolutionFromFileMenu()
    {
        // The native StopRun command disables continuous run before the file picker.
        continuousRun = false;
        var path = solutionFilePicker.Pick(this, OpenSolutionDirectoryPreference.InitialDirectory());
        if (string.IsNullOrWhiteSpace(path)) return;
        OpenSolutionDirectoryPreference.Remember(path);
        // Our independent executor must finish its current round before replacing its document.
        if (activeRun is not null) { StatusText.Text = "请等待当前流程运行结束"; return; }
        if (!ConfirmPendingChanges()) return;
        doc.Load(path);
        RecentSolutionStore.Update(doc.FilePath!);
        RefreshRecentSolutionsMenu();
    }
}

protected override async void OnClosing(CancelEventArgs e)
{
 base.OnClosing(e);if(e.Cancel||toolCloseReady||(toolDebugSessions.Count==0&&groupConfigurationWindows.Count==0))return;e.Cancel=true;if(toolClosePending)return;toolClosePending=true;activeRun?.Cancel();
 try{foreach(var groupWindow in groupConfigurationWindows.ToArray())await groupWindow.StopAndCloseAsync();foreach(var session in toolDebugSessions.ToArray()){try{await session.DisposeAsync();}catch(Exception error){StatusText.Text="调试关闭："+error.Message;}}}finally{toolDebugSessions.Clear();toolCloseReady=true;_ = Dispatcher.BeginInvoke(new Action(Close));}
}

async void DrainWorkflowBeforeClose(object? sender,System.ComponentModel.CancelEventArgs e)
{
 if(e.Cancel||closeDrainComplete||activeRun is null)return;
 e.Cancel=true;
 if(closeDrainPending)return;
 closeDrainPending=true;
 WindowContent.IsEnabled=false;
 StatusText.Text="正在停止流程并等待资源释放…";
 var closingRun=activeRun;
 closingRun.Cancel();
 try
 {
  while(ReferenceEquals(activeRun,closingRun))await Task.Delay(10);
 }
 finally
 {
  closeDrainComplete=true;
  _=Dispatcher.BeginInvoke(new Action(Close));
 }
}

